@php($editing=(bool)$event)<header><div><p>EVENT STUDIO</p><h2>{{ $editing?'Edit event':'Create an event' }}</h2><span>Give people a clear, welcoming picture of what to expect.</span></div><button type="button" class="workspace-dialog-close" data-workspace-dialog-close aria-label="Close"><x-ui.icon name="close" :size="18"/></button></header><div class="event-form-body"><section><h3>Event identity</h3><div class="event-form-grid"><label class="span-2">Title<input name="title" required maxlength="200" value="{{ old('title',$event->title??'') }}"></label><label>Category<input name="category" maxlength="80" value="{{ old('category',$event->category??'') }}"></label><label>Visibility<select name="status"><option value="draft" @selected(old('status',$event->status??'draft')==='draft')>Draft</option><option value="published" @selected(old('status',$event->status??'')==='published')>Published</option></select></label><label class="span-2">Description<textarea name="description" rows="4" maxlength="5000">{{ old('description',$event->description??'') }}</textarea></label><label class="span-2">Featured image URL<input name="image_url" maxlength="1000" value="{{ old('image_url',$event->image_url??'') }}" placeholder="https://… or /storage/…"></label><label class="span-2">Image description<input name="image_alt" maxlength="255" value="{{ old('image_alt',$event->image_alt??'') }}"></label></div></section><section><h3>Time, place and registration</h3><div class="event-form-grid"><label>Starts<input type="datetime-local" name="starts_at" required value="{{ old('starts_at',isset($event->starts_at)?\Illuminate\Support\Carbon::parse($event->starts_at)->format('Y-m-d\TH:i'):'') }}"></label><label>Ends<input type="datetime-local" name="ends_at" value="{{ old('ends_at',isset($event->ends_at)?\Illuminate\Support\Carbon::parse($event->ends_at)->format('Y-m-d\TH:i'):'') }}"></label><label>Location<input name="location" list="event-locations" value="{{ old('location',$event->location??'') }}